const menu=document.querySelector('.menu-toggle'),nav=document.querySelector('#navigation');
function closeMenu(){menu.setAttribute('aria-expanded','false');menu.setAttribute('aria-label','Otwórz menu');nav.classList.remove('open');document.body.classList.remove('menu-open');}
menu.addEventListener('click',()=>{const open=menu.getAttribute('aria-expanded')!=='true';menu.setAttribute('aria-expanded',String(open));menu.setAttribute('aria-label',open?'Zamknij menu':'Otwórz menu');nav.classList.toggle('open',open);document.body.classList.toggle('menu-open',open);});nav.querySelectorAll('a').forEach(a=>a.addEventListener('click',closeMenu));document.addEventListener('keydown',e=>{if(e.key==='Escape')closeMenu();});
if('IntersectionObserver' in window&&!matchMedia('(prefers-reduced-motion: reduce)').matches){const observer=new IntersectionObserver(entries=>entries.forEach(e=>{if(e.isIntersecting){e.target.classList.add('visible');observer.unobserve(e.target);}}),{threshold:.08});document.querySelectorAll('.reveal').forEach(el=>{el.classList.add('will-reveal');observer.observe(el);});}
document.querySelector('.compare input').addEventListener('input',e=>{e.target.parentElement.style.setProperty('--position',e.target.value+'%');e.target.setAttribute('aria-valuetext',e.target.value+' procent');});
document.querySelectorAll('[data-open]').forEach(b=>b.addEventListener('click',e=>{e.preventDefault();document.getElementById(b.dataset.open).showModal();}));document.querySelectorAll('.close-dialog').forEach(b=>b.addEventListener('click',()=>b.closest('dialog').close()));document.querySelectorAll('dialog').forEach(d=>d.addEventListener('click',e=>{if(e.target===d){const r=d.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)d.close();}}));document.querySelectorAll('[data-switch]').forEach(b=>b.addEventListener('click',()=>{b.closest('dialog').close();document.getElementById(b.dataset.switch).showModal();}));
const frames=[{src:'assets/dining-v2.webp',title:'Przestrzeń do spotkań'},{src:'assets/hero-v2.webp',title:'Spójna całość'},{src:'assets/bathroom-v2.webp',title:'Uważność na detal'}];let active=0;
function displayFrame(i){active=(i+frames.length)%frames.length;const f=frames[active];document.querySelector('#gallery-image').src=f.src;document.querySelector('#gallery-image').alt=f.title+' — kadr koncepcyjny';document.querySelector('#gallery-caption').textContent=`0${active+1} / 03 — ${f.title} · Koncepcja wnętrza`;}
document.querySelectorAll('.previous-project,.gallery-prev').forEach(b=>b.addEventListener('click',()=>displayFrame(active-1)));document.querySelectorAll('.next-project,.gallery-next').forEach(b=>b.addEventListener('click',()=>displayFrame(active+1)));document.querySelector('#portfolio-dialog').addEventListener('keydown',e=>{if(e.key==='ArrowLeft')displayFrame(active-1);if(e.key==='ArrowRight')displayFrame(active+1);});displayFrame(0);document.querySelector('#year').textContent=new Date().getFullYear();
document.querySelector('#contact-form').addEventListener('submit',e=>{e.preventDefault();const d=new FormData(e.currentTarget);const body=`Dzień dobry,\n\n${d.get('message')}\n\nImię i nazwisko: ${d.get('name')}\nE-mail: ${d.get('email')}\nTelefon: ${d.get('phone')||'Nie podano'}\nLokalizacja: ${d.get('location')||'Do ustalenia'}\nTyp: ${d.get('type')}\nMetraż: ${d.get('area')||'Do ustalenia'}\nZakres: ${d.get('scope')}\nTermin: ${d.get('date')||'Do ustalenia'}`;location.href=`mailto:dobryuklad.koszalin@gmail.com?subject=${encodeURIComponent('Zapytanie o projekt wnętrza')}&body=${encodeURIComponent(body)}`;document.querySelector('#form-status').textContent='Wiadomość jest gotowa do otwarcia w aplikacji pocztowej. Jeśli aplikacja się nie otworzyła, napisz bezpośrednio na adres powyżej.';});

document.querySelectorAll('[data-frame]').forEach(button=>button.addEventListener('click',()=>displayFrame(Number(button.dataset.frame))));
document.querySelectorAll('[data-scope]').forEach(button=>button.addEventListener('click',()=>{document.querySelector('#contact-form [name="scope"]').value=button.dataset.scope;}));
document.querySelector('.interlude-motion-toggle').addEventListener('click',e=>{const button=e.currentTarget;const paused=button.getAttribute('aria-pressed')!=='true';button.setAttribute('aria-pressed',String(paused));button.setAttribute('aria-label',paused?'Wznów cienie przerywnika':'Zatrzymaj cienie przerywnika');button.textContent=paused?'▶':'Ⅱ';button.closest('.project-interlude').classList.toggle('paused',paused);});
